function ringDistance(words: string[], target: string, start: number): number {
  const n = words.length;
  let best = Infinity;
  for (let i = 0; i < n; i++) {
    if (words[i] !== target) continue;
    const d = Math.abs(i - start);
    best = Math.min(best, d, n - d);
  }
  return best === Infinity ? -1 : best;
}

