function ringDistance(words: string[], target: string, start: number): number {
  const n = words.length;
  for (let k = 0; k <= Math.floor(n / 2); k++) {
    if (words[(start + k) % n] === target) return k;
    if (words[(start - k + n) % n] === target) return k;
  }
  return -1;
}

